  curV = v;
  try { v.t1 = t + R.f(E, t, gate, clamp(p.pitch || 1,.25,4), p); } finally { curV = null; }
  for (const s of v.src) if (s[1] > v.t1) v.t1 = s[1];
  v.w = R.w = made - m0 + 3;
  gv.e = v.t1 + .05; graves.push(gv); voices.push(v); lastAt[name] = t; E.stats.started++; E.last = v;
