 const ref=c.speedReference,published=ref?.status==='published',basis='実給電の推力と共通抵抗から計算',source=published&&/^https:\/\//.test(ref.source||'')?` <a href="${esc(ref.source)}" target="_blank" rel="noopener noreferrer">速度の資料</a>`:'';
