 const row=(name,value)=>`<div><dt>${name}</dt><dd>${value}</dd></div>`,duration=(value,unit)=>value==null?'不要':num(value,1)+' '+unit;
 const rows=[row('生命維持',`${num(c.lifeSupportCapacity||0)} 名分 · ${duration(c.lifeSupportHours,'時間')}`),row('宇宙服で運用',`${num(c.suitSeats||0)} / ${num(c.crew||0)} 名`),row('射出対応',`${num(c.ejectionSeats||0)} / ${num(c.crew||0)} 名`),row('撃墜時の生還率',fPct(c.ejectionSurvival||0)),row('ハイパー航法',stats.hyperClass?`${c.navReady?'準備完了':'未充足'}（${num(+(c.navCapacity||0).toFixed(2))}／必要 ${num(+(c.navDemand||0).toFixed(2))}）`:'ハイパードライブなし'),row('照準機器',fPct(c.targetRatio||0)),row('姿勢制御',fPct(c.maneuverRatio||0)),row('レーザーガス',duration(c.laserGasSeconds,'秒の連続射撃')),row('着陸支持',c.landingReady?'対応':'不足'),row('機器の消費電力',fW(c.power||0))].join('');
