// ---------- boot ----------
function readDraft(hot) {
  let s = null;
  try { if (hot && hot.design) s = C.deserialize(hot.design,{deferPlacementGeometry:true}); } catch (e) { s = null; }
  if (!s) { try { const d = LS.get('yard.draft3') || LS.get('yard.draft2'); if (d) s = C.deserialize(JSON.parse(d),{deferPlacementGeometry:true}); } catch (e) { s = null; } }
  return s;
}
function collectSources() {
  // Classic single-page layout (no boot loader): reuse this page's inline scripts.
  const scripts = Array.from(document.scripts).map(s => s.text || '');
  const pick = (needle) => scripts.find(t => t.includes(needle)) || '';
  const coreText = pick('const Core = (() =>'), gfx = pick('const Gfx = (() =>'), engine = pick('const YardEngine = (() =>');
  return coreText && gfx && engine ? [coreText, gfx, engine] : null;
}
function start(hot) {
  $('#tabs').innerHTML = TABS.map(([k, l]) => `<button type="button" role="tab" data-tab="${k}" aria-selected="false" class="tab-${k}">${l}</button>`).join('');
  $('#newHulls').innerHTML = Object.entries(C.HULLS).map(([k, v]) => `<button type="button" class="hullcard" data-newhull="${k}">${silhouette(v)}<span>${v.name}</span></button>`).join('');
  $('#refGrid').innerHTML = [...exampleList(false), ...exampleList(true)].map(e => `<button class="btn" data-reference="${e.key}">${esc(e.name)}<small>${esc(e.side)} · ${esc(exampleLine(e))}</small></button>`).join('');
  restoreRenderer(false,false);bindRendering();
  bindDesignUI();bind();bindEngineering();bindWing();bindRealism();bindReference();bindAviation();bindFleet();bindSurface();bindPlanCuts();bindLayout();bindSolidCuts();bindVertexEdit();bindUserParts();bindImport();bindTitle();bindTutorial();bindTrial();bindMulti();bindEdit();bindInspBar();bindDockToggle();bindShot();bindVoyage();bindRail();bindPalette();bindPlacementRepeat();bindSound();
  if (hot && hot.ui) { for (const k of ['tab', 'part', 'partTool', 'mirror', 'view', 'coded', 'fit', 'bridge', 'bridgeMode', 'bridgeEquipment', 'equipmentId', 'group', 'ped', 'batteryCaliber', 'batteryGuns']) if (hot.ui[k] != null) st[k] = hot.ui[k]; }
  st.fit=C.canonicalWeaponKind?.(st.fit)||st.fit;
  if(!BRIDGES.includes(st.bridge))st.bridge='podBridge';
  if(!['body','windows'].includes(st.bridgeMode))st.bridgeMode='body';
  if(!Object.hasOwn(C.EQUIPMENT,st.bridgeEquipment)||C.EQUIPMENT[st.bridgeEquipment].group!=='bridge')st.bridgeEquipment='isdBridge';
  if(!Object.hasOwn(C.EQUIPMENT,st.equipmentId)||C.EQUIPMENT[st.equipmentId].group==='bridge')st.equipmentId=null;
  if (st.view === 'cut') st.view = 'xray';
  if (st.tab === 'bridge') st.tab = 'mod';
  if (st.tab === 'sim' || st.tab === 'arm') st.tab = st.tab === 'arm' ? 'mod' : 'spec';
  syncHud();
  requestAnimationFrame(loop);
  if (window.claude && window.claude.hot && window.claude.hot.snapshot) {
    window.claude.hot.snapshot(() => ({design: ship ? designUISavedDesign() : null, ui: {tab: st.tab, part: st.part, partTool: st.partTool, mirror: st.mirror, view: st.view, coded: st.coded, fit: st.fit, bridge: st.bridge, bridgeMode:st.bridgeMode,bridgeEquipment:st.bridgeEquipment,equipmentId:st.equipmentId,group:st.group,ped: st.ped,batteryCaliber:st.batteryCaliber,batteryGuns:st.batteryGuns}}));
  }
  Store.init();
  window.__yard = {veObject: () => veObject(), designUI, designUIOpen: w => designUIOpen(w), designUIArm: () => designUIArm(), designUIClose: k => designUIClose(k), tool: () => tool(), get ship() { return ship; }, editorAuthoringReady: () => !!ship && ship.parts.filter(p=>C.isHullStructure(p)).every(editorOwnedHullReady), get stats() { return S; }, get retryTimer() { return renderRetryTimer; }, kickLoop: () => requestAnimationFrame(loop), st, draw: requestDraw, renderPanel: () => renderPanel(), fleet, fleetSetMode, renderHealth, restoreRenderer, view: () => view, setShip, C, pick, onTap, touch, eng, openExample, title: titleApi, meshStore, trial, trialCommand, trialStep: dt => trialStep(dt), trialCamera: dt => trialCamera(dt), trialStart: o => trialStart(o), trialJump: k => trialJump(k), spaceBattleLaunch: () => spaceBattleLaunch(), spaceStep: dt => spaceStep(dt), fleetAsset: k => fleetAsset(k), SYSTEMS, JUMP};
  const boot = window.KSBoot, draft = readDraft(hot);
  const engineStart = YardEngineClient.start(boot ? null : collectSources(), boot ? {workerReady: boot.workerReady} : {});
  engineStart.then(mode => {
    engineHello(mode); boot?.step('engine', 'done'); titleStatus();
    let downloads=null,preparation=null;
    const preparationStatus=()=>{const el=document.getElementById('preloadStatus');if(!el)return;const labels=[];if(downloads&&downloads.phase==='downloading')labels.push(`作例データを取得中 ${downloads.ready} / ${downloads.total}`);if(preparation&&!['unavailable','stopped'].includes(preparation.phase))labels.push(preparation.phase==='complete'&&!preparation.failed?'作例の準備が完了しました':preparation.phase==='complete'?`作例を準備しました ${preparation.ready} / ${preparation.total}`:`作例を準備中 ${preparation.ready} / ${preparation.total}`);el.hidden=!labels.length;el.replaceChildren(...labels.flatMap((label,i)=>{const span=document.createElement('span');span.textContent=label;return i?[document.createTextNode(' · '),span]:[span];}));};
    if(window.KSAssetCache){window.KSAssetDownloads?.stop();window.KSAssetDownloads=KSAssetCache.preloadAssets({assets:Object.values(YardFleetData.designs).map(e=>e.model?.preparedBlueprint).filter(Boolean),onProgress:s=>{downloads=s;window.dispatchEvent(new CustomEvent('ks-download-progress',{detail:s}));preparationStatus();}});window.KSAssetDownloads.done.then(()=>LocalExamples.seed()).catch(()=>{});}
    if(mode==='worker'&&boot?.createBackgroundWorker&&window.KSAssetCache){
      window.KSPreload?.stop();
      window.KSPreload=KSAssetCache.createPreloader({keys:EXAMPLES.map(e=>e.key),createWorker:()=>boot.createBackgroundWorker(),busy:()=>eng.waiting||eng.uploading||trial.on||fleet.mode!=='design'||!!voy.w&&!titleVisible(),onProgress:s=>{
        preparation=s;window.dispatchEvent(new CustomEvent('ks-preload-progress',{detail:s}));preparationStatus();
      }});
    }
  }).catch(e => { console.error(e); toast('設計エンジンを起動できませんでした'); });
  boot?.step('view', 'done');
  // Keep the draft available without blocking New or examples behind work the
  // player has not selected. Continue starts its preparation when requested.
  if (draft) { boot?.step('draft', 'skip'); setShip(draft, {keepHistory: true,deferPreparation:!!(boot||hot?.title)}); }
  else boot?.step('draft', 'skip');
  if (boot || hot?.title) showTitle(); else if (!draft) openExample('venator');
}

// ---------- title screen ----------
