    const A=pos[a],B=pos[b],on=q?.kind==='edge'&&q.index===i,path=`M${A.map(f).join(' ')}L${B.map(f).join(' ')}`;
    if(Math.hypot(A[0]-B[0],A[1]-B[1])<2)return '';
