// The record line is shown by default on wide screens and folded on phones.
const trialRecordsOn=()=>trial.showRecords??(window.innerWidth>=900);
function trialCommand(cmd){
 if(!trial.on)return;if(trial.cine)spaceCineEnd();
 if(cmd==='tele+')trialSetThrottle(trialThrottleCommand()+.01);else if(cmd==='tele-')trialSetThrottle(trialThrottleCommand()-.01);
 else if(cmd==='idle')trialSetThrottle(0);
 else if(cmd==='pd-auto')trialSetDefense(!trialDefenseEnabled());
 else if(cmd==='rudder+'||cmd==='rudder-')trial.rudder=C.clamp(trial.rudder+(cmd.endsWith('+')?1:-1),-2,2);
 else if(cmd==='level')trial.level=true;
 else if(cmd==='center'){trial.rudder=0;trial.level=false;}
 else if(cmd==='cam'){trialSetCam(TRIAL_CAMS[(TRIAL_CAMS.indexOf(trial.camMode)+1)%TRIAL_CAMS.length]);toast('視点：'+trialCamName(trial.camMode));}
 else if(cmd==='reset'){if(trial.rts){toast('艦隊戦の途中では再開始できません');return;}trialReset();}
 else if(cmd==='foil'||cmd==='foil:open'||cmd==='foil:close'){trialFoilCommand(cmd.split(':')[1]);return;}
 else if(cmd==='fireTap')trial.fireTap=.25;
 else if(cmd==='menu'){const m=$('#thMenu'),b=document.querySelector('[data-trial-cmd="menu"]');if(m){m.hidden=!m.hidden;b?.setAttribute('aria-expanded',String(!m.hidden));}return;}
 else if(cmd==='power'){const m=$('#thPower'),b=document.querySelector('[data-trial-cmd="power"]');if(m){m.hidden=!m.hidden;b?.setAttribute('aria-expanded',String(!m.hidden));}return;}
 else if(cmd==='pnext'){trialCommand('power');return;}
 else if(cmd.startsWith('pmode:')){trialSetPower(cmd.slice(6));}
 else if(cmd==='records'){trial.showRecords=!trialRecordsOn();}
 else if(cmd==='volley'){trialVolley();}
 else if(cmd==='escort'){trialEscortMode();}
 else if(cmd==='gunmode'||cmd.startsWith('gun:')){const ks=Object.keys(GUN_MODES),k=cmd==='gunmode'?ks[(ks.indexOf(trial.gunMode||'free')+1)%ks.length]:cmd.slice(4);if(!GUN_MODES[k])return;trial.gunMode=k;trial.gunTarget=null;const M=GUN_MODES[k];toast(`主砲：${M.name} — ${M.note}`);const mb=document.querySelector('[data-th="gunmenu"]');if(mb)mb.innerHTML=`主砲 ${M.name} <kbd>G</kbd>`;}
 else if(cmd==='shot'){shotSet(!shot.on);return;}
 else if(cmd==='mute'){sndToggle();return;}
 else if(cmd==='pause'){trialPause();return;}
 else if(cmd==='missile'){if(!trial.launchers.length){toast('ミサイル発射管がありません');return;}trial.mslOrder=true;}
 else if(cmd==='sw')trialSwFire();
 else if(cmd==='swmode'||cmd==='swnext')trialSwMode();
 else if(cmd.startsWith('swselect:'))trialSwSelect(cmd.slice(9));
 else if(cmd.startsWith('swfire:'))trialSwFire(Number(cmd.slice(7)));
 else if(cmd==='swarc'){trial.swArc=trial.swArc===false;toast(trial.swArc?'超兵器の射界（射程と射角）を表示します':'超兵器の射界を隠しました');}
 else if(cmd==='map'){if(trial.rts){toast('ジャンプは戦術図の「離脱」「増援」で命じます');return;}trialMapShow();return;}
 else if(cmd.startsWith('jump:')){trialJump(cmd.slice(5));}
 else if(cmd==='retry'){if(trial.rts)return;const r=$('#trialHud [data-th="result"]');if(r)r.hidden=true;trialReset();}
 else if(cmd==='resultClose'){const r=$('#trialHud [data-th="result"]');if(r)r.hidden=true;return;}
 else if(cmd==='exit'){trialStop();return;}
 trialHudUpdate(true);
}
// ---------- star systems ----------
// v22 The systems of the galaxy map (Galaxy, shared with the fleet battle), each with the planet the flight orbits:
// drawn per pixel in planet radii, a shipyard ring in its equatorial plane where there is one. A ship arrives at 20°
// latitude heading toward the equator, so a ring stands as an arch across the sky ahead, 8–18° up. The six first
// systems keep their planets and suns; the others take their sun from their name.
const SYSTEMS={};
for(const g of Galaxy.SYSTEMS){const v=g.v,ring=v.ring||null,alt=v.alt||Math.round(C.clamp(v.r*.027,120000,190000)),h=Galaxy.hash(g.key),az=(h%3600)/3600*Math.PI*2,el=.36+((h>>>12)%100)/100*.18;
 SYSTEMS[g.key]={key:g.key,name:g.name,note:g.note,short:g.short,region:g.region,planet:{radius:v.r,kind:v.k,axis:(v.axis||(ring?[-Math.cos(20*Math.PI/180),Math.sin(20*Math.PI/180),0]:[0,0,1])).slice(),ring,ringName:v.ringName||null,look:v.look||null},altitude:alt,floor:v.fl||Math.round(alt*.28),sun:(v.sun||[Math.cos(az),el,Math.sin(az)]).slice(),map:g.at,star:v.star?{name:v.star.name,kind:v.star.kind,ang:v.star.ang,color:v.star.color.slice()}:null};}
for(const s of Object.values(SYSTEMS))if(s.planet?.axis){const l=Math.hypot(...s.planet.axis)||1;s.planet.axis=s.planet.axis.map(x=>x/l);}
for(const s of Object.values(SYSTEMS)){const l=Math.hypot(...s.sun);s.sun=s.sun.map(x=>x/l);}
const trialSys=()=>SYSTEMS[trial.sysKey]||SYSTEMS.coruscant;
const trialPlanet=()=>{const s=trialSys();return {center:tv.scale(trial.P,-1),radius:s.planet.radius,sun:s.sun,kind:s.planet.kind,axis:s.planet.axis,ring:s.planet.ring,look:s.planet.look||null,star:s.star?{dir:s.sun,ang:s.star.ang,color:s.star.color}:null};};
function trialInitialPose(s){
 const radius=s.planet.radius+s.altitude;
 if(s.key!=='coruscant')return {P:[0,radius,0],R:[1,0,0,0,1,0,0,0,1]};
 // Begin above the evening/night side, with the sun four degrees below the
 // orbital horizon. Move the starting location, retaining the real planet lighting.
 const sun=tv.norm(s.sun),base=Math.abs(sun[1])<.99?[0,1,0]:[0,0,1],edge=tv.norm(tv.add(base,sun,-tv.dot(base,sun)));
 const dusk=Math.acos(C.clamp(s.planet.radius/radius,0,1))+4*Math.PI/180;
 const up=tv.norm(tv.add(tv.scale(edge,Math.cos(dusk)),sun,-Math.sin(dusk))),forward=tv.norm(tv.add(sun,up,-tv.dot(sun,up)));
 return {P:tv.scale(up,radius),R:trialFrame(forward,up)};
}
function trialDust(){const L=trial.p.len,H=C.clamp(L*2,1400,30000),n=280,pos=new Float32Array(n*3);for(let i=0;i<pos.length;i++)pos[i]=(Math.random()*2-1)*H;trial.dust={H,pos,col:new Uint8Array(n*4).map((_,i)=>i%4===3?120:170+(i%4)*14),size:new Float32Array(n).fill(Math.max(2,L*.0035))};}

// ---------- hyperspace ----------
