      const cmd = {prev: 'prev', next: 'next', mode: 'cam', action: 'side'}[a];
      if (cmd) { voySpectateCmd(cmd); return true; }
      if (a === 'menu') { voySpectateCmd('speed:' + (voy.speed ? 0 : voy.lastSpeed || 1)); return true; }
