window.KSInput?.setHost(PAD_HOST);

// ---- src/55_voyage.js ----
// ============================================================
// 航行 (voyage): patrol, fleet battle and — in a later version —
// missions. Fleet setup with the order of battle, the operational
// map of the sector, the tactical map of each battle, and the way
// into flying any ship of a battle in 3D. The rules live in Rts.
// ============================================================
const R = Rts;
const VOY_SPEEDS = [0, 1, 4, 16, 64];
const voy = {open: false, screen: null, setup: null, w: null, speed: 1, last: 0, designs: new Map(), pending: new Map(), sel: {group: null, ctg: null, sys: null, dest: null, units: [], wing: null, foe: null}, cmd: null, tab: 'ships', side: true,
 ops: {c: [2500, 2500], k: 0, fitted: false}, tac: {sys: null, c: [0, 0], mpp: 300, fitted: false}, flash: [], seenEv: 0, notes: [], pilot: null, log: []};

// ---------- designs ----------
// Examples come with precomputed profiles; saved and current designs are
// prepared by the engine (the same request also builds their 3D models).
function voyExampleDesigns() {
 const out = [];
 for (const d of Object.values(YardFleetData?.designs || {})) out.push({key: d.key, name: d.name, faction: d.faction || R.SIDE_OF[d.side] || 'empire', side: d.side, cls: d.cls, p: C.emptyDesignProfile(C.referenceSpeedProfile(d.p,d.key)), info: d.info, model: d.model, loadPreset: {air:d.air||[],ground:d.ground||[]}, src: 'example'});
 return out.sort((a, b) => (a.faction > b.faction) - (a.faction < b.faction) || b.info.len - a.info.len);
}
function voyDesign(key) { const d = voy.designs.get(key);if (d) return d;const m = /^([A-Za-z0-9_]+)#(republic|neutral|dark|cis)$/.exec(key || '');if (!m) return null;const b = voy.designs.get(m[1]);return b ? voyRegister({...b, key, base: b.key, paint: m[2], faction: Object.entries(VOY_PAINT[b.key] || {}).find(([, p]) => p === m[2])?.[0] || b.faction}) : null; }
function voyRegister(d) { voy.designs.set(d.key, d); return d; }
// The examples are entered once (saved designs prepared first must not keep them out: FACTION-001 prepares those early).
function voyEnsureExamples() { if (voy.exReady) return; for (const d of voyExampleDesigns()) if (!voy.designs.has(d.key)) voyRegister(d); voy.exReady = true; }
function voyProfileStale(d) { return d?.src==='example'&&(d.p?.catalogOnly===true||voyCostStale(d)); }
const VOY_COST_SIGNATURE=C.costModelSignature?.();
function voyCostStale(d) {
 if(d?.src!=='example')return false;
 return !!C.FLEET_PROFILE_VERSION&&d.p?.profileVersion!==C.FLEET_PROFILE_VERSION||VOY_COST_SIGNATURE!=null&&(d.model?.profileVersion!==C.FLEET_PROFILE_VERSION||d.model?.costVersion!==C.COST_MODEL?.version||d.model?.costSignature!==VOY_COST_SIGNATURE);
}
async function voyPrepare(source) {
 // source: 'current' | 'save:<id>' | example key
 const previous=voy.designs.get(source);
 if (previous&&!voyProfileStale(previous)) return previous;
 if (voy.pending.has(source)) return voy.pending.get(source);
 const job = (async () => {
  const a = await fleetAsset(source), S = a.stats, p = C.emptyDesignProfile(a.p);
  if(p.catalogOnly||previous?.src==='example'&&p.profileVersion!==C.FLEET_PROFILE_VERSION){
   // fleetAsset has already cached this response and uploaded its geometry.
   // Remove every alias too, so a retry can request the current worker result.
   for(const [key,cached]of fleet.assets)if(cached===a){fleet.assets.delete(key);view?.fleetCache?.delete(key);}
   throw new Error('stale example fleet profile');
  }
  // (a design of a made faction this device does not know serves every faction, as 全陣営 does)
  const df = C.DESIGN_FACTIONS[a.design?.faction] && a.design.faction !== 'any' ? a.design.faction : null, sv = /^save:(.+)-\d+$/.exec(a.key);
  const example=previous?.src==='example',d = {...(example?previous:{}),key: a.key, name: p.name || S.name || '設計艦', faction: example?previous.faction:df || voy.setup?.own || 'empire', anyFaction: example?false:!df, side: example?previous.side:'自作艦', cls: S.cls?.name || '', p, info: R.designInfo(S, p), model: {profileVersion:p.profileVersion,costVersion:C.COST_MODEL?.version,costSignature:VOY_COST_SIGNATURE}, loadPreset: example?previous.loadPreset:source==='current'||source.startsWith('save:')?null:C.builtinComplement(source), src: source.startsWith('save:') ? 'save' : source === 'current' ? 'current' : 'example', ...(sv ? {saveId: sv[1], craft: !!(a.design && C.isCraft(a.design))} : {})};
  voy.designs.set(source, d);voy.designs.set(a.key, d);return d;
 })();
 voy.pending.set(source, job);try { return await job; } finally { voy.pending.delete(source); }
}
// Fleet data is a fast catalogue, not a promise that an older cached combat
// profile matches the installed weapon model. Refresh only ships about to sail.
function voyProfileKeys(rows) {
 return [...new Set(rows.flatMap(sh=>[sh,...(sh.carried||[])]).map(sh=>voyShipDesign(sh)?.key).filter(Boolean))];
}
function voyConvoyProfileKeys(sides) {
 if(typeof R.convoyKit!=='function')return [];
 return [...new Set((sides||[]).flatMap(sd=>{const kit=R.convoyKit(sd.faction);return kit?[...(kit.ships||[]),...(kit.escorts||[]),kit.big].filter(k=>k&&voyDesign(k)):[];}))];
}
function voyProfilesStale(keys) { return keys.some(k=>voyProfileStale(voyDesign(k))); }
async function voyRequireProfiles(keys) {
 const stale=[...new Set(keys)].filter(k=>voyProfileStale(voyDesign(k)));if(!stale.length)return true;
 if(voy.profilePreparing)return false;voy.profilePreparing=true;showBusyOverlay('艦艇の性能を更新中…');
 try{for(const k of stale){const d=await voyPrepare(k);if(voyProfileStale(d))throw new Error('stale example fleet profile');}return true;}
 catch(e){console.warn('fleet profile not ready',e.message);toast('艦艇の性能を更新できません。もう一度出撃してください');return false;}
 finally{voy.profilePreparing=false;hideBusyOverlay();if(voy.screen==='setup')voyRenderSetup();}
}
const voyShort = n => String(n || '').split('｜')[0];

